local({
  id <- as.numeric(CNTSCHID)
  if_else(is.na(id) | id %% 100000 == 0, NA_character_, paste(.wave, sprintf("%.0f", id)))
})

local({
  cnt <- as.character(haven::zap_labels(CNT))
  nation <- lookup_values(
    if_else(cnt == "GBR", paste(.wave, STRATUM), NA_character_),
    lookup_country,
    default = NA_character_
  )
  coalesce(nation, lookup_values(cnt, lookup_country, default = "Unknown"))
})

case_when(
  is.na(ESCS) ~ "Unknown",
  as.numeric(ESCS) <=
    stats::ave(as.numeric(ESCS), paste(.wave, haven::zap_labels(CNT)), FUN = function(x) {
      stats::quantile(x, 0.4, na.rm = TRUE)
    }) ~ "Low",
  as.numeric(ESCS) <=
    stats::ave(as.numeric(ESCS), paste(.wave, haven::zap_labels(CNT)), FUN = function(x) {
      stats::quantile(x, 0.6, na.rm = TRUE)
    }) ~ "Medium",
  .default = "High"
)

local({
  days <- coalesce(as.numeric(ST032Q01NA), as.numeric(WB032Q01NA))
  if_else(days %in% 1:8, days - 1, NA_real_)
})
